import pycosat
n = 36
N = 2 * n
clauses = []
for v in range(1, n+1):
    for p in range(N - v - 1):
        clauses.append([p*(n) + (v-1) + 1])
for p in range(N):
    for v1 in range(1, n+1):
        for v2 in range(v1+1, n+1):
            if p + v1 + 1 < N and p + v2 + 1 < N:
                c1 = p*(n) + (v1-1) + 1
                c2 = p*(n) + (v2-1) + 1
                clauses.append([-c1, -c2])
            if p - v1 - 1 >= 0 and p - v2 - 1 >= 0:
                c1 = (p - v1 - 1)*(n) + (v1-1) + 1
                c2 = (p - v2 - 1)*(n) + (v2-1) + 1
                clauses.append([-c1, -c2])
print(len(clauses))
sol = pycosat.solve(clauses, verbose=0)
print(type(sol))

